select * from rhq_2025_tier1_admit_card where is_active=false;

select is_active,count(*) from rhq_2025_tier1_admit_card group by is_active limit 10;

select * from rhq_2025_tier1_admit_card where examdate='nan';

select distinct examdate from rhq_2025_tier1_admit_card ;

select distinct venue_code,examdate,shift,scribe_field,scribe_required,own_scribe,scribe_medium,count(*) from rhq_2025_tier1_admit_card
where is_active=true group by venue_code,examdate,shift,scribe_field,scribe_required,own_scribe,scribe_medium order by venue_code,examdate,shift;

alter table candidates add column debarred character varying;

select * from ey_re_schedule_rhq2025 limit 10;----1732

update rhq_2025_tier1_admit_card a
set a.is_active=true,
a.remarks='ey observation'
from ey_re_schedule_rhq2025 b
where a.reg_number=b.reg_number and a.roll_number=b.roll_number;


select distinct a.is_active,count(*) 
from rhq_2025_tier1_admit_card a,
ey_re_schedule_rhq2025 b
where a.reg_number=b.reg_number and a.roll_number=b.roll_number
group by a.is_active;


