select * from rhq_2025_tier1_admit_card_master_data_consolidated where reg_number='10022374025';
select count(*) from rhq_2025_tier1_admit_card_master_data_consolidated;

select * from rhq_2025_tier1_admit_card_master_data_consolidated where reg_number not in (select distinct reg_number from rhq_2025_tier1_admit_card);

where reg_number='10001217694';

select * from "rhq2025Applications_bkp07072025" where "registrationNo"='10021603447';

select a.* from
rhq_2025_tier1_admit_card a join
differnce_33k b on a.reg_number=b.reg_number;

select distinct level,count(*) from rhq_2025_tier1_admit_card where is_active=true group by level;

