'10000771196',
'10010378468',
'10015798953',
'10022238255',
'10009983446',
'10006672486',
'10013573174',
'10023416082'
)  and level='MATRIC' order by reg_number;

select a.* from
rhq_2025_tier1_admit_card a,
(SELECT 
    reg_number, 
    level
FROM rhq_2025_tier1_admit_card where is_active=true
GROUP BY reg_number, level
HAVING COUNT(DISTINCT roll_number) > 1)b
where a.reg_number=b.reg_number and a.level=b.level 
and a.is_active=true order by a.reg_number;


