select count(*) from rhq_2025_tier1_admit_card; -- 1167772

select count(*) from rhq_2025_tier1_admit_card where is_active=false;

SELECT 
    reg_number, 
    examdate
FROM rhq_2025_tier1_admit_card where is_active=true
GROUP BY reg_number, examdate
HAVING COUNT(DISTINCT venue_code) > 1;

SELECT c.*
FROM rhq_2025_tier1_admit_card c 
JOIN (
    SELECT reg_number, examdate
    FROM rhq_2025_tier1_admit_card
    GROUP BY reg_number, examdate
    HAVING COUNT(DISTINCT venue_code) > 1
) t ON c.reg_number = t.reg_number AND c.examdate = t.examdate
ORDER BY c.reg_number, c.examdate;

